import javax.swing.*;
import java.awt.*;

void main() {
  var frame = new JFrame("Spiral");
  frame.add(new Spiral());
  frame.setSize(400, 400);
  frame.setVisible(true);
}

class Spiral extends JPanel {
  Spiral() { setBackground(Color.BLACK); }

  public void paint(Graphics g) {
    super.paint(g);
    for (int i = 0; i < 300; i++) {
      double a = i * 0.25;
      double r = i * 0.6;
      int x = (int) (200 + Math.cos(a) * r);
      int y = (int) (200 + Math.sin(a) * r);
      float h = i / 300f;
      var c = Color.getHSBColor(h, 1, 1);
      g.setColor(c);
      g.fillOval(x, y, 8, 8);
    }
  }
}
